<div class="modal-body">
<div class="alert alert-warning"><?php echo app_lang('fiscal_draft_internal_notice'); ?></div>
<?php if($source_changed){?><div class="alert alert-danger"><?php echo app_lang('fiscal_draft_source_changed'); ?></div><?php } ?>
<h4><?php echo app_lang('fiscal_preparation').' '.$document->series.' '.$document->folio; ?></h4>
<h5><?php echo app_lang('document'); ?></h5>
<div class="row"><div class="col-md-3"><strong><?php echo app_lang('type'); ?>:</strong> <?php echo app_lang('fiscal_document_type_'.$document->document_type); ?></div><div class="col-md-3"><strong><?php echo app_lang('series'); ?>:</strong> <?php echo htmlspecialchars($document->series); ?></div><div class="col-md-3"><strong><?php echo app_lang('folio'); ?>:</strong> <?php echo(int)$document->folio; ?></div><div class="col-md-3"><strong><?php echo app_lang('status'); ?>:</strong> <?php echo app_lang('fiscal_draft_status_'.$document->status); ?></div></div>
<div class="row mt10"><div class="col-md-3"><strong><?php echo app_lang('date'); ?>:</strong> <?php echo format_to_datetime($document->issue_date); ?></div><div class="col-md-3"><strong><?php echo app_lang('currency'); ?>:</strong> <?php echo htmlspecialchars($document->currency_code); ?></div><div class="col-md-3"><strong><?php echo app_lang('exchange_rate'); ?>:</strong> <?php echo $document->exchange_rate!==null?htmlspecialchars($document->exchange_rate):'—'; ?></div><div class="col-md-3"><strong><?php echo app_lang('expedition_postal_code'); ?>:</strong> <?php echo htmlspecialchars($document->expedition_postal_code); ?></div></div>
<div class="row mt10"><div class="col-md-4"><strong><?php echo app_lang('sat_payment_form'); ?>:</strong> <?php echo htmlspecialchars($document->payment_form_code); ?></div><div class="col-md-4"><strong><?php echo app_lang('sat_payment_method'); ?>:</strong> <?php echo htmlspecialchars($document->payment_method_code); ?></div><div class="col-md-4"><strong><?php echo app_lang('cfdi_use'); ?>:</strong> <?php echo htmlspecialchars($document->cfdi_use_code); ?></div></div>
<hr><div class="row"><div class="col-md-6"><h5><?php echo app_lang('fiscal_issuer'); ?></h5><strong><?php echo htmlspecialchars($issuer->legal_name); ?></strong><br>RFC: <?php echo htmlspecialchars($issuer->rfc); ?><br><?php echo app_lang('tax_regime'); ?>: <?php echo htmlspecialchars($issuer->tax_regime_code); ?><br><?php echo app_lang('fiscal_postal_code'); ?>: <?php echo htmlspecialchars($issuer->fiscal_postal_code); ?></div><div class="col-md-6"><h5><?php echo app_lang('receiver'); ?></h5><strong><?php echo htmlspecialchars($receiver->legal_name); ?></strong><br>RFC: <?php echo htmlspecialchars($receiver->rfc); ?><br><?php echo app_lang('tax_regime'); ?>: <?php echo htmlspecialchars($receiver->tax_regime_code); ?><br><?php echo app_lang('fiscal_postal_code'); ?>: <?php echo htmlspecialchars($receiver->fiscal_postal_code); ?><br><?php echo app_lang('cfdi_use'); ?>: <?php echo htmlspecialchars($receiver->cfdi_use_code); ?></div></div>
<hr><h5><?php echo app_lang('items'); ?></h5><div class="table-responsive"><table class="table table-bordered"><thead><tr><th>#</th><th><?php echo app_lang('product_service_key'); ?></th><th><?php echo app_lang('description'); ?></th><th><?php echo app_lang('quantity'); ?></th><th><?php echo app_lang('unit_key'); ?></th><th><?php echo app_lang('unit_value'); ?></th><th><?php echo app_lang('discount'); ?></th><th><?php echo app_lang('tax_object_code'); ?></th><th><?php echo app_lang('taxes'); ?></th><th><?php echo app_lang('total'); ?></th></tr></thead><tbody><?php foreach($items as$i){?><tr><td><?php echo$i->line_number; ?></td><td><?php echo htmlspecialchars($i->product_service_code); ?></td><td><?php echo htmlspecialchars($i->description); ?></td><td><?php echo htmlspecialchars($i->quantity); ?></td><td><?php echo htmlspecialchars($i->unit_code); ?></td><td><?php echo to_currency($i->unit_value); ?></td><td><?php echo to_currency($i->discount); ?></td><td><?php echo htmlspecialchars($i->tax_object_code); ?></td><td><?php foreach($i->taxes as$t)echo htmlspecialchars($t->tax_code.' · '.$t->tax_type.' · '.$t->factor_type.($t->rate_or_quota!==null?' · '.$t->rate_or_quota:'' )).' · '.to_currency($t->amount).'<br>'; ?></td><td><?php echo to_currency($i->line_total); ?></td></tr><?php } ?></tbody></table></div>
<?php if($tax_totals){?><h5><?php echo app_lang('tax_summary'); ?></h5><div class="table-responsive"><table class="table table-bordered"><thead><tr><th><?php echo app_lang('code'); ?></th><th><?php echo app_lang('type'); ?></th><th><?php echo app_lang('rate'); ?></th><th><?php echo app_lang('subtotal'); ?></th><th><?php echo app_lang('total'); ?></th></tr></thead><tbody><?php foreach($tax_totals as$t){?><tr><td><?php echo htmlspecialchars($t->tax_code); ?></td><td><?php echo htmlspecialchars($t->tax_type.' · '.$t->factor_type); ?></td><td><?php echo $t->rate_or_quota!==null?htmlspecialchars($t->rate_or_quota):'—'; ?></td><td><?php echo to_currency($t->taxable_base); ?></td><td><?php echo to_currency($t->amount); ?></td></tr><?php } ?></tbody></table></div><?php } ?>
<h5><?php echo app_lang('totals'); ?></h5><table class="table table-bordered"><tr><td><?php echo app_lang('subtotal'); ?></td><td><?php echo to_currency($document->subtotal); ?></td></tr><tr><td><?php echo app_lang('discount'); ?></td><td><?php echo to_currency($document->discount); ?></td></tr><tr><td><?php echo app_lang('transferred_taxes'); ?></td><td><?php echo to_currency($document->transferred_tax_total); ?></td></tr><tr><td><?php echo app_lang('withheld_taxes'); ?></td><td><?php echo to_currency($document->withheld_tax_total); ?></td></tr><tr><th><?php echo app_lang('total'); ?></th><th><?php echo to_currency($document->total); ?></th></tr></table>
<?php if($document->status==='locked'){?><hr><h5><?php echo app_lang('prexml_cfdi40'); ?></h5><div class="alert alert-warning"><?php echo app_lang('prexml_no_fiscal_validity'); ?></div><?php if($artifact){?><dl><dt><?php echo app_lang('status'); ?></dt><dd><?php echo app_lang('prexml_status_'.$artifact->validation_status); ?></dd><dt>SHA-256</dt><dd><code><?php echo htmlspecialchars($artifact->sha256); ?></code></dd><dt><?php echo app_lang('size'); ?></dt><dd><?php echo(int)$artifact->byte_size; ?> bytes</dd><dt><?php echo app_lang('version'); ?></dt><dd><?php echo htmlspecialchars($artifact->builder_version.' · '.$artifact->schema_version); ?></dd></dl><div class="btn-group"><?php if($can_xml_view)echo modal_anchor(get_uri('fiscal/invoices/prexml/view/'.$artifact->id),app_lang('view_prexml'),['class'=>'btn btn-default','title'=>app_lang('prexml_cfdi40')]);if($can_xml_download){?><a class="btn btn-default" href="<?php echo get_uri('fiscal/invoices/prexml/download/'.$artifact->id); ?>"><?php echo app_lang('download_prexml'); ?></a><?php } ?></div><?php if($can_xml_validate){echo form_open(get_uri('fiscal/invoices/prexml/validate'),['id'=>'validate-prexml-form','class'=>'general-form d-inline']);?><input type="hidden" name="artifact_id" value="<?php echo$artifact->id; ?>"><button class="btn btn-default"><?php echo app_lang('validate_prexml'); ?></button><?php echo form_close();}}elseif($can_xml_generate){echo form_open(get_uri('fiscal/invoices/prexml/generate'),['id'=>'generate-prexml-form','class'=>'general-form']);?><input type="hidden" name="document_id" value="<?php echo$document->id; ?>"><button class="btn btn-success"><?php echo app_lang('generate_prexml'); ?></button><?php echo form_close();} ?></div><?php } ?>
<?php if($document->status==='locked'&&$artifact){?><hr><h5><?php echo app_lang('local_xml_sealing'); ?></h5><div class="alert alert-warning"><?php echo app_lang('signed_xml_not_stamped'); ?></div><?php if($signature){?><div class="alert alert-success"><?php echo app_lang('local_signature_correct'); ?></div><?php if($can_signed_view)echo modal_anchor(get_uri('fiscal/invoices/signed/view/'.$signature->signed_xml_artifact_id),app_lang('view_signed_xml'),['class'=>'btn btn-default','title'=>app_lang('local_xml_sealing')]);}elseif($can_sign){echo form_open(get_uri('fiscal/invoices/sign'),['id'=>'local-signing-form','class'=>'general-form']);?><input type="hidden" name="document_id" value="<?php echo(int)$document->id; ?>"><input type="hidden" name="pre_xml_artifact_id" value="<?php echo(int)$artifact->id; ?>"><div class="form-group row"><label class="col-md-4"><?php echo app_lang('digital_seal_certificate'); ?></label><div class="col-md-8"><?php echo form_dropdown('certificate_id',[''=>'-']+$certificates,'',"class='select2 form-control' required"); ?></div></div><div class="form-group row"><label class="col-md-4"><?php echo app_lang('private_key_password'); ?></label><div class="col-md-8"><input type="password" name="private_key_password" autocomplete="new-password" class="form-control" required><small><?php echo app_lang('csd_password_not_stored'); ?></small></div></div><button class="btn btn-success"><?php echo app_lang('sign_xml_locally'); ?></button><?php echo form_close();}} ?>
</div>
<div class="modal-footer"><button type="button" class="btn btn-default fiscal-review-back" data-action-url="<?php echo get_uri('fiscal/invoices/review/'.$document->invoice_id); ?>"><?php echo app_lang('back_to_fiscal_review'); ?></button><?php if(in_array($document->status,['draft','ready'],true)&&$can_lock){echo form_open(get_uri('fiscal/invoices/drafts/action'),['id'=>'lock-fiscal-draft','class'=>'general-form d-inline']);?><input type="hidden" name="document_id" value="<?php echo$document->id; ?>"><input type="hidden" name="action" value="lock"><button class="btn btn-primary"><?php echo app_lang('close_fiscal_preparation'); ?></button><?php echo form_close();}if(in_array($document->status,['draft','ready'],true)&&$can_cancel){echo form_open(get_uri('fiscal/invoices/drafts/action'),['id'=>'cancel-fiscal-draft','class'=>'general-form d-inline']);?><input type="hidden" name="document_id" value="<?php echo$document->id; ?>"><input type="hidden" name="action" value="cancel"><button class="btn btn-danger"><?php echo app_lang('cancel_internal_preparation'); ?></button><?php echo form_close();}?><button type="button" class="btn btn-default" data-bs-dismiss="modal"><?php echo app_lang('close'); ?></button></div>
<script>$(document).ready(function(){$('#local-signing-form .select2').select2();$('.fiscal-review-back').on('click',function(){var button=$(this),container=$('#ajaxModalContent');button.trigger('blur');$.post(button.data('action-url'),{ajaxModal:1},function(html){container.html(html);container.find('button,a,input,select').filter(':visible').first().trigger('focus');});});$('#lock-fiscal-draft,#cancel-fiscal-draft,#generate-prexml-form,#validate-prexml-form,#local-signing-form').appForm({onSuccess:function(){location.reload();}});});</script>
